import math

class Solution:
    def loss(self, logits: list[list[float]], targets: list[int]) -> float:
        total=0.0
        for row,target in zip(logits,targets):
            peak=max(row)
            total+=peak+math.log(sum(math.exp(v-peak) for v in row))-row[target]
        return total/len(targets)

